# safe "or" helper used in many places
`%||%` <- function(a, b) {
    if (is.null(a)) return(b)
    if (is.logical(a) && length(a) == 1 && is.na(a)) return(b)
    if (is.character(a) && length(a) == 1 && a == "") return(b)
    a
}


