# ---- Utilities ----

SPLIT_PATTERN <- "^([A-Za-z]+)(\\d+)(?:\\.(\\d+))?"

logger_info <- function(...) if (verbose) message("[INFO] ", paste(..., collapse=" "))
logger_debug <- function(...) if (verbose) message("[DEBUG] ", paste(..., collapse=" "))

remove_leading_icd <- function(entry) {
  prefixes <- c("ICD10:", "ICD10-CM:", "ICD9:", "ICD9-CM:", "ICD8:")
  res <- entry
  if (is.character(entry) && length(entry) == 1 && !is.na(entry)) {
    for (p in prefixes) {
      if (startsWith(entry, p)) {
        res <- substring(entry, nchar(p) + 1)
        break
      }
    }
  }
  logger_debug("[remove_leading_icd] entry:", entry, "res:", res)
  return(res)
}

as_list <- function(x) {
  if (is.null(x)) return(list())
  if (is.list(x)) {
    seq <- x
  } else if (is.atomic(x) && length(x) > 1) {
    seq <- as.list(x)
  } else {
    seq <- list(x)
  }
  seq <- Filter(function(i) !is.na(i) && str_trim(as.character(i)) != "", seq)
  seq
}

to_dt_list <- function(x) {
  arr <- as_list(x)
  if (length(arr) == 0) return(list())
  parsed <- lapply(arr, function(v) {
    if (is.na(v) || v == "") return(NA)
    s <- as.character(v)
    # Try various formats
    dt <- suppressWarnings(parse_date_time(s, orders = c("Ymd", "Y-m-d", "d/m/Y", "m/d/Y", "Ymd HMS", "Y-m-d H:M:S")))
    if (is.na(dt)) return(NA)
    as.POSIXct(dt)
  })
  parsed[!sapply(parsed, is.na)]
}

convert_if_not_datetime <- function(val) {
  if (is.null(val) || is.na(val)) return(NA)
  if (inherits(val, c("Date", "POSIXct", "POSIXt"))) return(as.POSIXct(val))
  dt <- suppressWarnings(parse_date_time(as.character(val), orders = c("Y-m-d", "d/m/Y", "m/d/Y", "Ymd")))
  if (is.na(dt)) return(NA)
  as.POSIXct(dt)
}

format_numeric <- function(entry, Mode) {
  eM <- Mode %in% DK_clusters
  s <- as.character(entry)
  parts <- strsplit(s, "\\.", fixed = TRUE)[[1]]
  intp <- parts[1]
  decp <- if (length(parts) > 1) parts[2] else ""
  if (eM && nzchar(intp)) intp <- str_pad(intp, 3, pad = "0")
  if (eM && nzchar(decp)) decp <- str_pad(decp, 2, pad = "0")
  if (nzchar(decp)) paste0(intp, ".", decp) else intp
}

split_and_format <- function(input_str, fill = FALSE) {
  if (is.numeric(input_str) || (is.character(input_str) && grepl("^\\d+$", input_str))) return(as.character(input_str))
  s <- as.character(input_str)
  m <- regexec(SPLIT_PATTERN, s)
  r <- regmatches(s, m)[[1]]
  if (length(r) >= 3) {
    string_part <- r[2]; integer_part <- r[3]; decimal_part <- ifelse(length(r) >= 4, r[4], NA)
    combined <- ifelse(is.na(decimal_part) || decimal_part == "NULL", integer_part, paste0(integer_part, decimal_part))
    if (fill) combined <- str_pad(combined, 4, side = "right", pad = "0")
    return(paste0(string_part, combined))
  }
  as.character(input_str)
}

# -----------------------------------------------------------------------------
# process_entry / update_icd_coding / dict_update_icd_coding / parse_pheno_rules
# -----------------------------------------------------------------------------

process_entry <- function(entry, remove_leading = FALSE, eM = FALSE, mode = "Default", icdprefix = "", remove_point = FALSE, ICDCM = FALSE) {
  # ported logic from Python process_entry
  remove_leading_flag <- tolower(as.character(remove_leading)) %in% c("true", "1", "yes", "y")
  if (is.null(entry) || is.na(entry)) return(NA)
  if (!is.character(entry)) {
    if (is.numeric(entry) && floor(entry) == entry) {
      if (only_ICD10) return(NULL)
      return(format_numeric(entry, mode))
    }
    return(as.character(entry))
  }
  # ATC pass-through
  if (startsWith(entry, "ATC:")) {
    if (only_ICD10 || only_ICD9 || only_ICD8) return(NULL)
    if (ATC_Requested == "None") ATC_Requested <<- "Some"
    res <- if (remove_leading_flag) sub("^ATC:", "", entry) else entry
    if (mode %in% DK_clusters && remove_leading_flag) res <- paste0("ATC:", toupper(gsub("\\.", "", sub("^ATC:", "", entry))))
    if (remove_point) res <- gsub("\\.", "", res)
    return(res)
  }
  if (startsWith(entry, "ICD8:")) {
    if (only_ICD10 || only_ICD9) return(NULL)
    new_entry <- sub("^ICD8:", "", entry)
    if (mode %in% DK_clusters) {
      newval <- format_numeric(new_entry, mode)
      entry2 <- paste0("ICD8:", newval)
    } else {
      entry2 <- entry
    }
    res <- if (remove_point) gsub("\\.", "", entry2) else entry2
    if (remove_leading_flag) res <- sub("^ICD8:", "", res)
    return(toupper(res))
  }
  if (startsWith(entry, "ICD9-CM:")) {
    if (only_ICD10 || only_ICD8) return(NULL)
    if (ICDCM) {
      res <- sub("^ICD9-CM:", "", entry)
      res <- if (remove_leading_flag) res else paste0("ICD9-CM:", res)
      if (remove_point) res <- gsub("\\.", "", res)
      return(toupper(res))
    }
    return(NULL)
  }
  if (startsWith(entry, "ICD10-CM:")) {
    if (only_ICD8 || only_ICD9) return(NULL)
    if (ICDCM) {
      res <- sub("^ICD10-CM:", "", entry)
      res <- if (remove_leading_flag) res else paste0("ICD10-CM:", res)
      if (remove_point) res <- gsub("\\.", "", res)
      return(toupper(res))
    }
    return(NULL)
  }
  if (startsWith(entry, "ICD9:")) {
    if (only_ICD10 || only_ICD8) return(NULL)
    res <- sub("^ICD9:", "", entry)
    res <- if (remove_leading_flag) res else paste0("ICD9:", res)
    if (remove_point) res <- gsub("\\.", "", res)
    return(toupper(res))
  }
  # ICD10 or plain codes
  if (startsWith(entry, "ICD10:") || startsWith(entry, icdprefix)) {
    if (only_ICD8 || only_ICD9) return(NULL)
    # normalize prefix usage
    if (nzchar(icdprefix)) {
      if (!startsWith(entry, "ICD10:") && !startsWith(entry, icdprefix)) {
        res <- paste0("ICD10:", icdprefix, toupper(sub("^ICD10:", "", entry)))
      } else if (startsWith(entry, icdprefix)) {
        res <- toupper(entry)
        res <- if (remove_leading_flag) res else paste0("ICD10:", res)
      } else if (startsWith(entry, paste0("ICD10:", icdprefix))) {
        res <- toupper(entry)
        res <- if (remove_leading_flag) sub("^ICD10:", "", res) else res
      } else {
        res <- sub("^ICD10:", "", entry) |> toupper() |> paste0(icdprefix, .)
        res <- if (remove_leading_flag) res else paste0("ICD10:", res)
      }
    } else {
      res <- sub("^ICD10:", "", entry) |> toupper()
      res <- if (remove_leading_flag) res else paste0("ICD10:", res)
    }
    if (remove_point) res <- gsub("\\.", "", res)
    if (remove_leading_flag) res <- sub("^ICD10:", "", res)
    return(res)
  }
  # generic heuristics for DK cluster
  res <- entry
  if (mode %in% DK_clusters && !grepl("^\\d+$", entry) && !startsWith(toupper(entry), "ATC")) {
    entry_clean <- str_trim(entry)
    if (grepl("^[A-Z]{2}\\d", entry_clean, ignore.case = TRUE)) {
      res <- toupper(gsub("\\.", "", entry_clean))
      res <- if (remove_leading_flag) res else paste0("ICD10:", res)
    } else if (grepl("^[A-Z](?:\\d|$)", entry_clean, ignore.case = TRUE)) {
      normalized <- toupper(gsub("\\.", "", entry_clean))
      res <- paste0(icdprefix, normalized)
      res <- if (remove_leading_flag) res else paste0("ICD10:", res)
    } else {
      res <- gsub("\\.", "", entry_clean)
    }
  } else {
    entry_clean <- str_trim(entry)
    res <- if (nzchar(icdprefix)) paste0(icdprefix, gsub("\\.", "", entry_clean)) else gsub("\\.", "", entry_clean)
    res <- if (remove_leading_flag) res else paste0("ICD10:", res)
  }
  # final cleaning
  for (tag in c("ATC:", "ICD8:", "ICD9:", "ICD10:", "ICD9-CM:", "ICD10-CM:", "ICD9CM:", "ICD10CM:")) {
    if (startsWith(toupper(res), toupper(tag))) {
      if (remove_leading_flag) res <- sub(paste0("^", tag), "", res)
      break
    }
  }
  if (remove_point) res <- gsub("\\.", "", res)
  res
}

update_icd_coding <- function(data, eM = FALSE, skip = FALSE, remove_point_in_diag_request = FALSE, ICDCM = FALSE, noLeadingICD = FALSE, icdprefix = "") {
  logger_info("[update_icd_coding] Starting update_icd_coding with:", paste(data, collapse=","))
  if (skip) return(data)
  entries <- data
  if (!is.vector(entries) && !is.list(entries)) entries <- as.vector(entries)
  output <- list()
  for (entry in entries) {
    p <- process_entry(entry = entry, remove_leading = noLeadingICD, eM = eM, mode = cluster_run, icdprefix = icdprefix, remove_point = remove_point_in_diag_request, ICDCM = ICDCM)
    logger_debug("[update_icd_coding] processed entry:", entry, "->", p)
    if (!is.null(p) && !is.na(p)) output <- c(output, p)
  }
  if (cluster_run %in% DK_clusters) {
    output <- Filter(function(x) !(startsWith(x, "ICD10-CM:") || startsWith(x, "ICD9-CM:")), output)
  }
  logger_info("[update_icd_coding] Final updated ICD codes:", paste(output, collapse=","))
  output
}

is_advanced_rule_string <- function(val) {
  if (!is.character(val)) return(FALSE)
  any(grepl("main=|sub=|rule_out=|-", val)) && !grepl("-CM", val)
}

parse_pheno_rules <- function(rule_str, exact_match = FALSE, skip_icd_update = FALSE, remove_point_in_diag_request = FALSE, ICDCM = FALSE, noLeadingICD = FALSE, icdprefix = "") {
  rule <- list(main = list(), sub = list(), rule_out = list(), main_exact = list(), sub_exact = list(), rule_out_exact = list(), ranges = list())
  logger_info("[parse_pheno_rules] trying to split", rule_str)
  if (grepl(";", rule_str, fixed = TRUE)) {
    parts <- strsplit(rule_str, ";", fixed = TRUE)[[1]]
    for (part in parts) {
      if (!grepl("=", part, fixed = TRUE)) next
      kv <- strsplit(part, "=", fixed = TRUE)[[1]]
      key <- str_trim(kv[1]); val <- str_trim(kv[2])
      val_list <- strsplit(val, ",", fixed = TRUE)[[1]] |> trimws()
      updated <- update_icd_coding(data = expand_ranges(val_list), eM = exact_match, skip = skip_icd_update, remove_point_in_diag_request = remove_point_in_diag_request, ICDCM = ICDCM, noLeadingICD = noLeadingICD, icdprefix = icdprefix)
      rule[[key]] <- updated
    }
  } else {
    val_list <- strsplit(rule_str, ",", fixed = TRUE)[[1]] |> trimws()
    rule$ranges <- update_icd_coding(data = expand_ranges(val_list), eM = exact_match, skip = skip_icd_update, remove_point_in_diag_request = remove_point_in_diag_request, ICDCM = ICDCM, noLeadingICD = noLeadingICD, icdprefix = icdprefix)
  }
  logger_info("[parse_pheno_rules] result:", paste(unlist(rule), collapse = ","))
  rule
}

dict_update_icd_coding <- function(curr_codes, exact_match = FALSE, skip_icd_update = FALSE, remove_point_in_diag_request = FALSE, ICDCM = FALSE, noLeadingICD = FALSE, icdprefix = "") {
  # curr_codes: data.frame with columns 'Disorder' and 'Disorder Codes' (strings or lists)
  updated_list_out <- list()
  if (!("Disorder" %in% names(curr_codes)) || !("Disorder Codes" %in% names(curr_codes))) {
    stop("dict_update_icd_coding expects a data.frame with 'Disorder' and 'Disorder Codes'")
  }
  for (i in seq_len(nrow(curr_codes))) {
    disorder <- curr_codes$Disorder[i]
    raw <- curr_codes$`Disorder Codes`[i]
    updated_list <- list()
    advanced_dict <- NULL
    if (is.vector(raw) && any(sapply(raw, is.character) & sapply(raw, is_advanced_rule_string))) {
      # advanced mode: parse each sublist / string
      for (sub in raw) {
        if (is_advanced_rule_string(sub)) {
          advanced_dict <- parse_pheno_rules(sub, exact_match = exact_match, skip_icd_update = skip_icd_update, remove_point_in_diag_request = remove_point_in_diag_request, ICDCM = ICDCM, noLeadingICD = noLeadingICD, icdprefix = icdprefix)
        } else {
          raw_list <- if (is.character(sub)) strsplit(sub, ",", fixed = TRUE)[[1]] |> trimws() else as.character(sub)
          updated <- update_icd_coding(raw_list, eM = exact_match, skip = skip_icd_update, remove_point_in_diag_request = remove_point_in_diag_request, ICDCM = ICDCM, noLeadingICD = noLeadingICD, icdprefix = icdprefix)
          updated_list <- c(updated_list, updated)
        }
      }
    } else if (is.character(raw) && is_advanced_rule_string(raw)) {
      advanced_dict <- parse_pheno_rules(raw, exact_match = exact_match, skip_icd_update = skip_icd_update, remove_point_in_diag_request = remove_point_in_diag_request, ICDCM = ICDCM, noLeadingICD = noLeadingICD, icdprefix = icdprefix)
    } else {
      # normalize raw to vector
      if (is.list(raw)) {
        raw_list <- unlist(raw)
      } else if (is.character(raw) && grepl(",", raw, fixed = TRUE)) {
        raw_list <- strsplit(raw, ",", fixed = TRUE)[[1]] |> trimws()
      } else if (is.character(raw)) {
        raw_list <- if (nzchar(raw)) raw else character(0)
      } else {
        raw_list <- character(0)
      }
      if (length(raw_list) > 0) {
        updated <- update_icd_coding(raw_list, eM = exact_match, skip = skip_icd_update, remove_point_in_diag_request = remove_point_in_diag_request, ICDCM = ICDCM, noLeadingICD = noLeadingICD, icdprefix = icdprefix)
        updated_list <- c(updated_list, updated)
      }
    }
    # If advanced_dict is present, construct textual representation and also a flattened normalized list
    if (!is.null(advanced_dict)) {
      txt <- character()
      if (length(advanced_dict$main) > 0) {
        txt <- c(txt, paste0("main=", paste(unique(advanced_dict$main), collapse = ",")))
      }
      if (length(advanced_dict$sub) > 0) {
        txt <- c(txt, paste0("sub=", paste(unique(advanced_dict$sub), collapse = ",")))
      }
      if (length(advanced_dict$rule_out) > 0) {
        txt <- c(txt, paste0("rule_out=", paste(unique(advanced_dict$rule_out), collapse = ",")))
      }
      final_txt <- paste(txt, collapse = ";")
      updated_list <- c(updated_list, unlist(advanced_dict$main), unlist(advanced_dict$sub), unlist(advanced_dict$rule_out))
      curr_codes$`Disorder Codes`[i] <- list(final_txt)
    } else {
      curr_codes$`Disorder Codes`[i] <- list(updated_list)
    }
    updated_list_out[[i]] <- updated_list
  }
  normalized <- unique(unlist(updated_list_out))
  list(curr_codes, normalized)
}

expand_ranges <- function(code_list) {
  # Accepts character vector or single comma string; returns expanded vector
  if (is.null(code_list)) return(character(0))
  if (length(code_list) == 1 && grepl(",", code_list)) {
    tokens <- strsplit(code_list, ",", fixed = TRUE)[[1]] |> trimws()
  } else if (is.character(code_list)) tokens <- code_list |> trimws() else tokens <- as.character(code_list)
  expanded <- character()
  parse_side <- function(s) {
    s <- trimws(s)
    if (s == "") return(NULL)
    pref <- ""
    rest <- s
    if (grepl(":", s)) {
      parts <- strsplit(s, ":", fixed = TRUE)[[1]]
      pref <- paste0(parts[1], ":")
      rest <- parts[2]
    }
    m <- regexec("^([A-Za-z]{1,2})(\\d+)(?:\\.(\\d+))?$", rest)
    r <- regmatches(rest, m)[[1]]
    if (length(r) >= 3) {
      letters <- r[2]; num <- as.integer(r[3])
      return(list(pref = pref, letters = letters, num = num))
    }
    if (grepl("^\\d+$", rest)) return(list(pref = pref, letters = "", num = as.integer(rest)))
    return(NULL)
  }
  for (token in tokens) {
    token <- trimws(as.character(token))
    if (token == "") next
    if (!grepl("-", token)) { expanded <- c(expanded, token); next }
    parts <- strsplit(token, "-", fixed = TRUE)[[1]]
    left_raw <- trimws(parts[1]); right_raw <- trimws(parts[2])
    if (grepl("^\\d+$", left_raw) && grepl("^\\d+$", right_raw)) {
      s <- as.integer(left_raw); e <- as.integer(right_raw)
      if (s <= e) expanded <- c(expanded, as.character(seq(s, e))) else expanded <- c(expanded, token)
      next
    }
    lp <- parse_side(left_raw); rp <- parse_side(right_raw)
    if (!is.null(lp) && !is.null(rp) && lp$letters == rp$letters && lp$num <= rp$num) {
      use_pref <- ifelse(nzchar(lp$pref), lp$pref, rp$pref)
      if (nzchar(lp$letters)) {
        expanded <- c(expanded, vapply(seq(lp$num, rp$num), function(i) paste0(use_pref, lp$letters, i), character(1)))
      } else {
        expanded <- c(expanded, as.character(seq(lp$num, rp$num)))
      }
      next
    }
    m2 <- regexec("^([A-Za-z]{1,2})(\\d+)-\\1(\\d+)$", gsub(" ", "", token))
    r2 <- regmatches(gsub(" ", "", token), m2)[[1]]
    if (length(r2) >= 4) {
      letters <- r2[2]; s <- as.integer(r2[3]); e <- as.integer(r2[4])
      if (s <= e) expanded <- c(expanded, vapply(seq(s, e), function(i) paste0(letters, i), character(1))) else expanded <- c(expanded, token)
      next
    }
    expanded <- c(expanded, token)
  }
  unique(expanded)
}

# -----------------------------------------------------------------------------
# HDF5 / indexed access and helpers (select_by_iid_and_diag_optimized, get_h5_cases)
# Note: In R we implement simplified HDF5 logic or rely on data.table::fread for CSVs.
# -----------------------------------------------------------------------------

# For brevity and robustness, the R translation reads CSVs; advanced HDF5 indexing can be added later.
# Implement select_by_iid_and_diag_optimized as a wrapper around data.table reading with filters.
select_by_iid_and_diag_optimized <- function(input_csv, iidcol, iids = NULL, diagcol, diags = NULL, columns = NULL, chunksize = 200000, prefix_all = FALSE, sep = ",") {
  # If file is small, read all and filter; otherwise use fread with select.
  dt <- data.table::fread(input_csv, sep = sep, select = unique(c(iidcol, diagcol, columns)), showProgress = FALSE)
  if (!is.null(diags)) {
    diags <- unlist(diags)
    prefixes <- diags[grepl("\\*$", diags)]
    exacts <- setdiff(diags, prefixes)
    mask <- rep(FALSE, nrow(dt))
    s <- as.character(dt[[diagcol]])
    if (length(exacts) > 0) mask <- mask | (s %in% exacts)
    if (length(prefixes) > 0) {
      ps <- sub("\\*$", "", prefixes)
      for (p in ps) mask <- mask | startsWith(s, p)
    }
    dt <- dt[mask, ]
  }
  if (!is.null(iids)) {
    dt <- dt[dt[[iidcol]] %in% iids, ]
  }
  as.data.frame(dt)
}

get_h5_cases <- function(h5file, iids, iidcol, diags, diagcol, directmapping = TRUE, table_name = "df", is_advanced_pheno = FALSE) {
  # In R translation we accept h5file as CSV or .h5 not implemented; assume CSV path
  # This wrapper attempts to read using select_by_iid_and_diag_optimized
  logger_info("[get_h5_cases] h5file:", h5file, "exists?", file.exists(h5file))
  diags_flat <- unlist(diags)
  df <- select_by_iid_and_diag_optimized(input_csv = h5file, iidcol = iidcol, iids = iids, diagcol = diagcol, diags = diags_flat, columns = NULL, prefix_all = !directmapping, sep = ",")
  logger_debug("[get_h5_cases] result rows:", nrow(df))
  df
}

h5_load_df1 <- function(h5_file, iids, iidcol, flattened_pheno_requests, exact_match, BuildEntryExitDates, diagnostic_col, birthdatecol, ctype_col) {
  logger_info("[h5_load_df1] loading from", h5_file)
  cases <- get_h5_cases(h5file = h5_file, iids = iids, iidcol = iidcol, diags = flattened_pheno_requests, diagcol = diagnostic_col, directmapping = exact_match)
  df1 <- finalize_lpr_data(cases, diagnostic_col = diagnostic_col, birthdatecol = birthdatecol, ctype_col = ctype_col, verbose = verbose)
  if (BuildEntryExitDates) logger_info("[h5_load_df1] BuildEntryExitDates not implemented for h5 path")
  df1
}

# -----------------------------------------------------------------------------
# Core phenotype building functions: map_cases, advanced_map_cases, build_phenotype_cases
# -----------------------------------------------------------------------------

map_cases <- function(values_to_match, exact_match, df1, diagcol, cols = NULL) {
  out <- data.frame()
  if (is.null(values_to_match) || length(values_to_match) == 0) {
    logger_info("[map_cases] No values_to_match supplied")
    return(out)
  }
  prefixes <- c(); exacts <- c()
  for (d in as.character(values_to_match)) {
    d <- trimws(d)
    if (!exact_match || grepl("\\*$", d)) {
      prefixes <- c(prefixes, ifelse(grepl("\\*$", d), substr(d, 1, nchar(d) - 1), d))
    } else {
      exacts <- c(exacts, d)
    }
  }
  s <- as.character(df1[[diagcol]])
  mask <- rep(FALSE, nrow(df1))
  if (length(exacts) > 0) mask <- mask | (s %in% exacts)
  if (length(prefixes) > 0) {
    for (p in prefixes) mask <- mask | startsWith(s, p)
  }
  if (any(mask)) {
    if (!is.null(cols)) out <- df1[mask, cols, drop = FALSE] else out <- df1[mask, , drop = FALSE]
  }
  out
}

detect_advanced_cases <- function(df, rule_dict, input_date_in_name, exact_match, diagcol, iidcol) {
  # Implemented simplified version of Python detect_advanced_cases
  main_df <- df[df$type %in% c("A", "G", "C"), , drop = FALSE]
  sub_df  <- df[df$type %in% c("+", "B"), , drop = FALSE]
  all_df  <- df
  ruleout_ids <- character(0)
  if (length(rule_dict$rule_out) > 0) {
    idx <- which(sapply(all_df[[diagcol]], function(d) any(startsWith(as.character(d), rule_dict$rule_out))))
    ruleout_ids <- unique(c(ruleout_ids, as.character(all_df[[iidcol]][idx])))
  }
  # mains with +sub
  raw_main <- rule_dict$main
  mains_with_sub <- gsub("\\+sub$", "", raw_main[grepl("\\+sub$", raw_main)])
  mains_normal <- setdiff(raw_main, mains_with_sub)
  matched_frames <- list()
  # mains that require sub
  for (m in mains_with_sub) {
    main_match <- map_cases(m, exact_match, main_df, diagcol)
    sub_match <- map_cases(rule_dict$sub, exact_match, sub_df, diagcol)
    if (nrow(main_match) > 0 && nrow(sub_match) > 0) {
      both <- merge(main_match, sub_match, by = c(iidcol, input_date_in_name))
      matched_frames[[length(matched_frames) + 1]] <- both
    }
  }
  # mains normal
  if (length(mains_normal) || length(rule_dict$main_exact)) {
    main_match <- map_cases(mains_normal, exact_match, main_df, diagcol)
    if (length(rule_dict$sub)) sub_match <- map_cases(rule_dict$sub, exact_match, sub_df, diagcol) else sub_match <- data.frame()
    combined <- unique(bind_rows(main_match, sub_match))
    matched_frames[[length(matched_frames) + 1]] <- combined
  }
  if (length(matched_frames)) {
    matched <- unique(bind_rows(matched_frames))
  } else {
    matched <- data.frame()
  }
  if (nrow(matched) > 0 && length(ruleout_ids) > 0) {
    matched <- matched[!matched[[iidcol]] %in% ruleout_ids, , drop = FALSE]
  }
  matched
}

advanced_map_cases <- function(values_to_match, df1, exact_match, diagnostic_col, input_date_in_name, iidcol, skip_icd_update = FALSE, remove_point_in_diag_request = FALSE, ICDCM = FALSE, noLeadingICD = FALSE, icdprefix = FALSE) {
  if (is.character(values_to_match) && grepl("main=", values_to_match)) {
    rule_dict <- parse_pheno_rules(values_to_match, exact_match = exact_match, skip_icd_update = skip_icd_update, remove_point_in_diag_request = remove_point_in_diag_request, ICDCM = ICDCM, noLeadingICD = noLeadingICD, icdprefix = icdprefix)
    tmp_result_df <- detect_advanced_cases(df1, rule_dict, input_date_in_name, exact_match, diagnostic_col, iidcol)
    if (nrow(tmp_result_df) > 0) tmp_result_df$diagnosis <- "[Advanced Rule]"
  } else {
    tmp_result_df <- map_cases(values_to_match = values_to_match, exact_match = exact_match, df1 = df1, diagcol = diagnostic_col)
  }
  tmp_result_df
}

merge_IIDs <- function(tmp_result_df, diagnostic_col, birthdatecol, input_date_in_name, input_date_out_name, iidcol, verbose = FALSE, Cases = TRUE, Covariates = FALSE, BuildEntryExitDates = FALSE) {
  if (nrow(tmp_result_df) == 0) return(tmp_result_df)
  dt <- as.data.table(tmp_result_df)
  cols <- unique(c(iidcol, diagnostic_col, input_date_in_name, input_date_out_name, birthdatecol, "pattype", "admissiontype", "diagtype", "source", "register"))
  cols <- cols[cols %in% names(dt)]
  dt <- dt[, ..cols]
  # normalize dates
  if (!("date_in" %in% names(dt)) && input_date_in_name %in% names(dt)) setnames(dt, input_date_in_name, "date_in")
  if (!("date_out" %in% names(dt)) && input_date_out_name %in% names(dt)) setnames(dt, input_date_out_name, "date_out")
  if (!("date_out" %in% names(dt))) dt[, date_out := date_in]
  # coerce to POSIX
  if ("date_in" %in% names(dt)) dt[, date_in := as.POSIXct(sapply(date_in, convert_if_not_datetime))]
  if ("date_out" %in% names(dt)) dt[, date_out := as.POSIXct(sapply(date_out, convert_if_not_datetime))]
  # group summaries
  bycols <- iidcol
  first_dates <- dt[, .(first_dx = min(date_in, na.rm = TRUE)), by = bycols]
  last_dates  <- dt[, .(last_dx = max(date_out, na.rm = TRUE)), by = bycols]
  merges <- list(first_dates, last_dates)
  if (Cases || Covariates) {
    dx_list <- dt[, .(diagnoses = list(na.omit(as.character(get(diagnostic_col))))), by = bycols]
    merges <- c(merges, list(dx_list))
  }
  in_dates <- dt[, .(in_dates = list(as.character(date_in))), by = bycols]
  out_dates <- dt[, .(out_dates = list(as.character(date_out))), by = bycols]
  merges <- c(merges, list(in_dates, out_dates))
  if ("source" %in% names(dt)) merges <- c(merges, list(dt[, .(source = list(source)), by = bycols]))
  if ("diagtype" %in% names(dt)) merges <- c(merges, list(dt[, .(diagtype = list(diagtype)), by = bycols]))
  if ("register" %in% names(dt)) merges <- c(merges, list(dt[, .(register = list(register)), by = bycols]))
  if (Cases) {
    n_diags <- dt[, .(n_diags = sum(!is.na(date_in))), by = bycols]
    n_unique <- dt[, .(n_unique_in_days = length(unique(as.Date(date_in)))), by = bycols]
    merges <- c(merges, list(n_diags, n_unique))
  }
  id_dx_date_df <- Reduce(function(x, y) merge(x, y, by = iidcol, all = TRUE), merges)
  tmp_iids <- unique(dt[[iidcol]])
  tmp_df <- data.table::data.table(iid = tmp_iids)
  setnames(tmp_df, "iid", iidcol)
  tmp_df[, diagnosis := ifelse(Cases, "Case", "Control")]
  dx_result_df <- merge(tmp_df, id_dx_date_df, by = iidcol, all.x = TRUE)
  # set diagnosis after merge to ensure missing diagnoses become Control
  if (Cases) {
    if ("diagnoses" %in% names(dx_result_df)) {
      has_diag <- sapply(dx_result_df$diagnoses, function(x) { if (is.null(x)) FALSE else (length(x) > 0) })
    } else {
      has_diag <- rep(FALSE, nrow(dx_result_df))
    }
    dx_result_df$diagnosis <- ifelse(has_diag, "Case", "Control")
  } else {
    dx_result_df$diagnosis <- "Control"
  }
  as.data.frame(dx_result_df)
}

build_phenotype_cases <- function(df1, exact_match, values_to_match, diagnostic_col, birthdatecol, iidcol, input_date_in_name, input_date_out_name, verbose = FALSE, Covariates = FALSE, Covar_Name = "", general_results = data.frame(), BuildEntryExitDates = FALSE, skip_icd_update = FALSE, remove_point_in_diag_request = FALSE, ICDCM = FALSE, noLeadingICD = FALSE, icdprefix = "") {
  # df1 can be a list [df_noatc, df_atc] or a single df
  if (is.list(df1) && length(df1) >= 2) {
    df_noatc <- df1[[1]]; df_atc <- df1[[2]]
    vals_noatc <- values_to_match[[1]]; vals_atc <- values_to_match[[2]]
    diag_noatc <- diagnostic_col[[1]]; diag_atc <- diagnostic_col[[2]]
    date_noatc <- input_date_in_name[[1]]; date_atc <- input_date_in_name[[2]]
    tmp_result_df <- advanced_map_cases(vals_noatc, df_noatc, exact_match, diag_noatc, date_noatc, iidcol, skip_icd_update, remove_point_in_diag_request, ICDCM, noLeadingICD, icdprefix)
    tmp_result_df_atc <- advanced_map_cases(vals_atc, df_atc, exact_match, diag_atc, date_atc, iidcol, skip_icd_update, remove_point_in_diag_request, ICDCM, noLeadingICD, icdprefix)
    if (nrow(tmp_result_df_atc) > 0) {
      # harmonize names
      if (diag_atc != diag_noatc) names(tmp_result_df_atc)[names(tmp_result_df_atc) == diag_atc] <- diag_noatc
      if (date_atc != date_noatc) names(tmp_result_df_atc)[names(tmp_result_df_atc) == date_atc] <- date_noatc
    }
    tmp_result_df <- bind_rows(tmp_result_df, tmp_result_df_atc)
    diagnostic_col <- diag_noatc
    input_date_in_name <- date_noatc
    if (is.list(input_date_out_name)) input_date_out_name <- input_date_out_name[[1]]
  } else {
    tmp_result_df <- advanced_map_cases(values_to_match, df1, exact_match, diagnostic_col, input_date_in_name, iidcol, skip_icd_update, remove_point_in_diag_request, ICDCM, noLeadingICD, icdprefix)
  }
  if (nrow(tmp_result_df) == 0) {
    if (!Covariates) logger_info("[build_phenotype_cases] ERROR: No cases found")
    return(data.frame())
  }
  # convert date columns
  conv <- function(colname) {
    if (colname %in% names(tmp_result_df)) tmp_result_df[[colname]] <<- sapply(tmp_result_df[[colname]], convert_if_not_datetime)
  }
  if (is.list(input_date_in_name)) lapply(input_date_in_name, conv) else conv(input_date_in_name)
  if (is.list(input_date_out_name)) lapply(input_date_out_name, conv) else conv(input_date_out_name)
  if (!is.null(birthdatecol) && birthdatecol %in% names(tmp_result_df)) conv(birthdatecol)
  merged <- merge_IIDs(tmp_result_df = tmp_result_df, diagnostic_col = diagnostic_col, birthdatecol = birthdatecol, input_date_in_name = input_date_in_name, input_date_out_name = input_date_out_name, iidcol = iidcol, verbose = verbose, Cases = TRUE, Covariates = Covariates, BuildEntryExitDates = BuildEntryExitDates)
  if (!Covariates) return(merged)
  # Covariate formatting
  keep_cols <- c(iidcol, "diagnosis", "diagnoses", "in_dates", "out_dates", "first_dx", "last_dx", "n_diags", "n_unique_in_days")
  keep_cols <- intersect(keep_cols, names(merged))
  covar <- merged[, keep_cols, drop = FALSE]
  covar <- covar[!duplicated(covar[[iidcol]]), , drop = FALSE]
  if (nrow(general_results) > 0) covar <- merge(general_results, covar, by = iidcol)
  covar
}

# -----------------------------------------------------------------------------
# Exclusion logic: build_ExDEP_exclusions, update_DxDates_multi_exclusion, Exclusion_interpreter
# -----------------------------------------------------------------------------

build_ExDEP_exclusions <- function(casecontrol_df, df1, diagnostic_col, iidcol, birthdatecol, input_date_in_name, input_date_out_name, diag_df, diag, exact_match, verbose = FALSE, get_earliest_date_from_data = TRUE, dbds_run = FALSE, extra_cols_to_keep = character(0), skip_icd_update = FALSE, remove_point_in_diag_request = FALSE, ICDCM = FALSE, noLeadingICD = FALSE, icdprefix = "") {
  if (verbose) logger_info("[build_ExDEP_exclusions] Running build_phenotype_cases for", diag)
  filtered_df <- build_phenotype_cases(df1 = df1, exact_match = exact_match, values_to_match = diag_df, diagnostic_col = diagnostic_col, birthdatecol = birthdatecol, iidcol = iidcol, input_date_in_name = input_date_in_name, input_date_out_name = input_date_out_name, verbose = verbose, Covariates = TRUE, Covar_Name = diag, skip_icd_update = skip_icd_update, remove_point_in_diag_request = remove_point_in_diag_request, ICDCM = ICDCM, noLeadingICD = noLeadingICD, icdprefix = icdprefix)
  base_cols <- c(iidcol, "diagnoses", "in_dates", "out_dates", "first_dx")
  if (nrow(filtered_df) > 0) {
    # rename and merge
    rename_map <- c("diagnoses" = diag, "in_dates" = paste0(diag, "_In_Dates"), "out_dates" = paste0(diag, "_Out_Dates"), "first_dx" = paste0(diag, "_earliest_date"), "last_dx" = paste0(diag, "_latest_date"))
    for (k in names(rename_map)) if (k %in% names(filtered_df)) names(filtered_df)[names(filtered_df) == k] <- rename_map[[k]]
    for (col in extra_cols_to_keep) if (col %in% names(filtered_df)) names(filtered_df)[names(filtered_df) == col] <- paste0(diag, "_", col)
    if (is.null(casecontrol_df) || nrow(casecontrol_df) == 0) casecontrol_df <- filtered_df[, c(iidcol), drop = FALSE]
    casecontrol_df <- merge(casecontrol_df, filtered_df, by = iidcol, all = TRUE)
    # ensure default empties for lists/strings
    for (col in c(diag, paste0(diag, "_In_Dates"), paste0(diag, "_Out_Dates"))) {
      if (!col %in% names(casecontrol_df)) casecontrol_df[[col]] <- ""
      casecontrol_df[[col]][is.na(casecontrol_df[[col]])] <- ""
    }
  } else {
    # ensure columns exist
    cols_needed <- c(diag, paste0(diag, "_In_Dates"), paste0(diag, "_Out_Dates"), paste0(diag, "_earliest_date"), paste0(diag, "_latest_date"))
    for (col in cols_needed) if (!col %in% names(casecontrol_df)) casecontrol_df[[col]] <- ifelse(grepl("_earliest|_latest", col), as.POSIXct(NA), "")
    for (col in extra_cols_to_keep) {
      newcol <- paste0(diag, "_", col)
      if (!newcol %in% names(casecontrol_df)) casecontrol_df[[newcol]] <- ""
    }
  }
  casecontrol_df
}

update_DxDates_multi_exclusion <- function(all_data, exclusion_type, exc_diag, exc_diag_date, exc_diag_inflicted_changes, diag_excode, level2codes, level2dates, level2datemodifiercodes, level2datemodifierdates, level2datemodifierDXs, date_format = "%Y-%m-%d", verbose = FALSE) {
  out <- as.data.frame(all_data)
  # helper routines (local copies to deal with list/strings)
  as_list_local <- function(x) {
    if (is.list(x)) return(x)
    if (is.character(x) && grepl(",", x)) return(strsplit(x, ",")[[1]] |> trimws())
    if (is.na(x) || x == "") return(list())
    list(x)
  }
  to_dt_list_local <- function(x) {
    lst <- as_list_local(x)
    if (length(lst) == 0) return(list())
    parsed <- lapply(lst, function(z) {
      if (is.na(z) || z == "") return(NA)
      suppressWarnings(as.POSIXct(parse_date_time(as.character(z), orders = c("Y-m-d", "Ymd", "d/m/Y", "m/d/Y"))))
    })
    parsed[!sapply(parsed, is.na)]
  }
  n <- nrow(out)
  # ensure columns exist and are list-columns
  for (col in c(level2codes, level2dates, level2datemodifiercodes, level2datemodifierdates, level2datemodifierDXs, "in_dates", "diagnoses", "Level2_ExclusionReason")) {
    if (!col %in% names(out)) out[[col]] <- replicate(n, list())
    if (!is.list(out[[col]])) out[[col]] <- lapply(out[[col]], function(v) as_list_local(v))
  }
  # selection mask
  sel <- sapply(seq_len(n), function(i) {
    a <- out[[exc_diag]][i]
    b <- out[["diagnoses"]][i]
    !(is.na(a) || a == "") && !(is.na(b) || b == "")
  })
  idxs <- which(sel)
  for (i in idxs) {
    exc_dx_list <- as_list_local(out[[exc_diag]][i])
    exc_date_list <- to_dt_list_local(out[[exc_diag_date]][i])
    lvl2_codes <- as_list_local(out[[level2codes]][i])
    lvl2_dates <- to_dt_list_local(out[[level2dates]][i])
    in_diags <- as_list_local(out[["diagnoses"]][i])
    in_dates <- to_dt_list_local(out[["in_dates"]][i])
    exclusion_type_l <- tolower(exclusion_type)
    mod_pos <- integer(0); keep_pos <- seq_along(lvl2_dates) - 1; mod_pos_exc <- integer(0); mod_pos_orig <- integer(0)
    if (exclusion_type_l == "1yprior") {
      mod_pos <- integer(0); keep_pos <- integer(0)
      if (length(lvl2_dates) > 0 && length(exc_date_list) > 0) {
        for (j in seq_along(lvl2_dates)) {
          d <- lvl2_dates[[j]]
          diffs <- sapply(exc_date_list, function(ed) as.integer(difftime(d, ed, units = "days")))
          if (any(diffs <= 365 & diffs >= 0)) mod_pos <- c(mod_pos, j) else keep_pos <- c(keep_pos, j)
        }
        # mod_pos_exc indices are those exc_date_list indices implicated; create mod_pos_exc set
        mod_pos_exc <- unique(unlist(lapply(mod_pos, function(j) which((as.integer(difftime(lvl2_dates[[j]], exc_date_list, units = "days")) <= 365) & (as.integer(difftime(lvl2_dates[[j]], exc_date_list, units = "days")) >= 0)))))
      } else {
        mod_pos <- integer(0); keep_pos <- seq_along(lvl2_dates)
      }
    } else if (exclusion_type_l == "post") {
      if (length(exc_date_list) == 0) {
        mod_pos <- integer(0); keep_pos <- seq_along(lvl2_dates); mod_pos_exc <- integer(0); earliest <- NULL
      } else {
        earliest <- min(exc_date_list)
        mod_pos <- which(sapply(lvl2_dates, function(d) !is.na(d) && d >= earliest))
        keep_pos <- which(sapply(lvl2_dates, function(d) is.na(d) || d < earliest))
        mod_pos_exc <- which(sapply(exc_date_list, function(ed) ed == earliest))
      }
      mod_pos_orig <- which(sapply(in_dates, function(d) !is.na(d) && (!is.null(earliest) && d >= earliest)))
    } else if (exclusion_type_l == "lifetime") {
      mod_pos <- seq_along(lvl2_dates)
      keep_pos <- integer(0)
      mod_pos_exc <- seq_along(exc_date_list)
      mod_pos_orig <- seq_along(in_dates)
    } else {
      next
    }
    # Update level2 lists: keep elements at keep_pos
    new_codes <- if (length(keep_pos) > 0) lvl2_codes[keep_pos] else list()
    new_dates <- if (length(keep_pos) > 0) lapply(lvl2_dates[keep_pos], function(d) format(d, date_format)) else list()
    out[[level2codes]][i] <- list(new_codes)
    out[[level2dates]][i] <- list(new_dates)
    # Append modifiers
    exist_mod_dates <- as_list_local(out[[level2datemodifierdates]][i])
    exist_mod_codes <- as_list_local(out[[level2datemodifiercodes]][i])
    exist_mod_dxs <- as_list_local(out[[level2datemodifierDXs]][i])
    mod_dates_add <- if (length(mod_pos_exc) > 0 && length(exc_date_list) > 0) lapply(mod_pos_exc, function(j) format(exc_date_list[[j]], date_format)) else list()
    mod_codes_add <- if (length(mod_pos_exc) > 0 && length(exc_dx_list) > 0) exc_dx_list[mod_pos_exc] else list()
    mod_dxs_add <- rep(exc_diag, length(mod_codes_add))
    out[[level2datemodifierdates]][i] <- list(c(unlist(exist_mod_dates), unlist(mod_dates_add)))
    out[[level2datemodifiercodes]][i] <- list(c(unlist(exist_mod_codes), unlist(mod_codes_add)))
    out[[level2datemodifierDXs]][i] <- list(c(unlist(exist_mod_dxs), unlist(mod_dxs_add)))
    # inflicted changes
    if (!is.null(out$diagnosis) && out$diagnosis[i] == "Case" && length(mod_pos_orig) > 0) {
      out[[exc_diag_inflicted_changes]][i] <- length(mod_pos_orig)
    } else {
      out[[exc_diag_inflicted_changes]][i] <- 0
    }
    out[[paste0(exc_diag_inflicted_changes, "_MDD_dates")]][i] <- list(if (length(mod_pos_orig) > 0) lapply(in_dates[mod_pos_orig], function(d) format(d, date_format)) else list())
    out[[paste0(exc_diag_inflicted_changes, "_MDD_codes")]][i] <- list(if (length(mod_pos_orig) > 0) in_diags[mod_pos_orig] else list())
    out[[paste0(exc_diag_inflicted_changes, "_MDD_dXnumber")]][i] <- if (length(in_dates) > 0 && !is.na(out[[exc_diag]][i]) && out$diagnosis[i] == "Case") length(in_dates) else 0
    out[[paste0("[update_DxDates_multi_exclusion] MDD_diagnoses_in_percent_lost_due_to_", exc_diag)]][i] <- if (length(in_dates) > 0) (length(mod_pos_orig) / max(length(in_dates), 1)) * 100 else 0
  }
  # Append Level2_ExclusionReason for modified Case rows
  sel_idx <- idxs[sapply(idxs, function(i) !is.null(out$diagnosis) && out$diagnosis[i] == "Case")]
  if (length(sel_idx) > 0) {
    for (i in sel_idx) {
      existing <- as_list_local(out$Level2_ExclusionReason[[i]])
      out$Level2_ExclusionReason[[i]] <- unique(c(existing, diag_excode))
    }
  }
  out
}

Exclusion_interpreter <- function(data, min_Age = 0, max_Age = 0, lifetime_exclusions = data.frame(), oneYearPrior_exclusions = data.frame(), post_exclusions = data.frame(), date_format = "%Y-%m-%d", verbose = FALSE) {
  out <- as.data.frame(data)
  cols_to_drop <- c('temp_Level2_dates','diagnosis','diagnoses','first_dx','in_dates','c_diagtype','Age_FirstDx','birthdate','temp_birthdate')
  list_cols <- c('diagnoses_Level2_modifier', 'disorder_Level2_modifier', 'date_Level2_modifier', 'Level2_diagnoses', 'Level2_dates', 'Level2_ExclusionReason', 'Level2_FirstDx')
  n <- nrow(out)
  for (col in list_cols) if (!col %in% names(out)) out[[col]] <- replicate(n, list())
  if ("diagnoses" %in% names(out)) out$Level2_diagnoses <- lapply(out$diagnoses, as_list) else out$Level2_diagnoses <- replicate(n, list())
  if ("in_dates" %in% names(out)) out$Level2_dates <- lapply(out$in_dates, as_list) else out$Level2_dates <- replicate(n, list())
  if (!"Level2_AgeExclusion" %in% names(out)) out$Level2_AgeExclusion <- rep("False", n)
  # Age-based exclusion
  if (!is.null(min_Age) || !is.null(max_Age)) {
    first_dx_vec <- sapply(out$in_dates, function(x) { dts <- to_dt_list(x); if (length(dts) == 0) NA else min(unlist(dts)) })
    birth <- if ("birthdate" %in% names(out)) sapply(out$birthdate, convert_if_not_datetime) else rep(NA, n)
    age_years <- floor(as.numeric(difftime(as.POSIXct(first_dx_vec), as.POSIXct(birth), units = "days")) / 365)
    age_years[is.na(age_years)] <- NA
    out$Age_FirstDx <- age_years
    mask_age_excl <- (!is.na(age_years) & ((age_years < min_Age) | ((age_years > max_Age) & (max_Age > 0))))
    if (any(mask_age_excl, na.rm = TRUE)) {
      out$Level2_AgeExclusion[mask_age_excl] <- "True"
      for (i in which(mask_age_excl)) {
        out$Level2_ExclusionReason[[i]] <- unique(c(as_list(out$Level2_ExclusionReason[[i]]), "Age"))
      }
    }
  }
  # Apply tables
  apply_table_safe <- function(df, table_df, etype) {
    if (is.null(table_df) || nrow(table_df) == 0 || !("Disorder" %in% names(table_df))) return(df)
    exclNumber <- 1
    for (disorder in table_df$Disorder) {
      if (verbose) logger_debug("Applying", etype, "exclusion for", disorder)
      if (!disorder %in% names(df)) {
        exclNumber <- exclNumber + 1
        next
      }
      has_rows <- (as.character(df$diagnoses) != "") & (as.character(df[[disorder]]) != "")
      if (any(has_rows, na.rm = TRUE)) {
        df <- update_DxDates_multi_exclusion(df, etype, disorder, paste0(disorder, "_In_Dates"), paste0(disorder, "_Inflicted_changes"), exclNumber, "Level2_diagnoses", "Level2_dates", "diagnoses_Level2_modifier", "date_Level2_modifier", "disorder_Level2_modifier", date_format = date_format, verbose = verbose)
      }
      exclNumber <- exclNumber + 1
    }
    df
  }
  out <- apply_table_safe(out, oneYearPrior_exclusions, "1yprior")
  out <- apply_table_safe(out, post_exclusions, "post")
  out <- apply_table_safe(out, lifetime_exclusions, "lifetime")
  # AgeExclusion -> clear Level2
  mask_age_true <- out$Level2_AgeExclusion == "True"
  if (any(mask_age_true, na.rm = TRUE)) {
    for (i in which(mask_age_true)) {
      out$Level2_dates[[i]] <- list()
      out$Level2_diagnoses[[i]] <- list()
      out$disorder_Level2_modifier[[i]] <- unique(c(as_list(out$disorder_Level2_modifier[[i]]), "Age"))
    }
  }
  # Level2_FirstDx
  out$Level2_FirstDx <- lapply(out$Level2_dates, function(xs) { dts <- to_dt_list(xs); if (length(dts) == 0) list() else list(min(unlist(dts))) })
  # recalc age
  birth <- if ("birthdate" %in% names(out)) sapply(out$birthdate, convert_if_not_datetime) else rep(NA, n)
  first_dx0 <- sapply(out$Level2_FirstDx, function(xs) if (length(xs) > 0) xs[[1]] else NA)
  first_dx0 <- sapply(first_dx0, convert_if_not_datetime)
  out$Level3_Age_FirstDx <- floor(as.numeric(difftime(first_dx0, birth, units = "days")) / 365)
  out$Level3_Age_FirstDx[is.na(out$Level3_Age_FirstDx)] <- 0
  # Case/Control final labels
  out$Level3_CaseControl <- "Control"
  out$Level3_CaseControl[out$diagnosis == "Case"] <- "Case_Excluded"
  has_level2_first <- sapply(out$Level2_FirstDx, function(xs) length(xs) > 0)
  out$Level3_CaseControl[has_level2_first] <- "Case"
  # drop temps if present
  dropcols <- intersect(cols_to_drop, names(out))
  if (length(dropcols)) out <- out[, !(names(out) %in% dropcols), drop = FALSE]
  out
}

