remove_duplicates_preserve_order <- function(lst) {
  if (is.null(lst) || length(lst) == 0) return(list())
  seen <- character(0); out <- list()
  for (x in lst) {
    if (!(x %in% seen)) { seen <- c(seen, x); out <- c(out, x) }
  }
  out
}

Sankey_build_processor <- function(row, sankey_labels = c("MDD","Age","ID","SCZ","BPD","DEM","AUD","DUD","MCI","CTI","ClinPlausMDD"), main_diag = "MDD", lifetime_excl = c("ID","SCZ","BPD")) {
  # row is a list-like environment; we operate on it and return updated
  if (row$Level2_AgeExclusion == "TRUE") {
    row$Level3_Sankey <- list(main_diag, "Age")
    row$Level3_Sankey_data <- list(0,1)
    row$Level3_Sankey_source <- list(0)
    row$Level3_Sankey_target <- list(1)
    row$Level3_Sankey_value <- list(1)
    row$temp_exc_diag_date <- list()
    row$temp_exc_diag <- list()
    return(row)
  }
  if (length(row$diagnoses_Level2_modifier) == 0) {
    row$Level3_Sankey <- list(main_diag)
    row$Level3_Sankey_data <- list(0)
    row$Level3_Sankey_source <- list(0)
    row$Level3_Sankey_target <- list(length(sankey_labels))
    row$Level3_Sankey_value <- list(1)
    row$temp_exc_diag_date <- list()
    row$temp_exc_diag <- list()
    return(row)
  }
  temp_exc_diag <- row$temp_exc_diag
  temp_exc_diag_date <- row$temp_exc_diag_date
  previous_exc_diag <- ""
  while (length(temp_exc_diag) > 0) {
    if (is.null(row$Level3_Sankey) || length(row$Level3_Sankey) == 0) row$Level3_Sankey <- list(main_diag)
    currently_earliest_exc_diag_date <- if (length(temp_exc_diag_date) > 0) min(unlist(temp_exc_diag_date)) else NA
    if (!is.na(currently_earliest_exc_diag_date)) {
      pos <- which(sapply(temp_exc_diag_date, function(d) identical(d, currently_earliest_exc_diag_date)))
    } else pos <- integer(0)
    keep_pos <- setdiff(seq_along(temp_exc_diag_date), pos)
    current_exc_diag <- temp_exc_diag[pos]
    if (length(current_exc_diag) > 0 && nzchar(current_exc_diag[[1]])) {
      currently_earliest_exc_disorder <- row$disorder_Level2_modifier[pos][[1]][1]
      currently_earliest_exc_disorder_numeric <- which(sankey_labels == currently_earliest_exc_disorder) - 1
      if (length(currently_earliest_exc_disorder_numeric) && !is.na(currently_earliest_exc_disorder_numeric)) {
        row$Level3_Sankey <- c(row$Level3_Sankey, currently_earliest_exc_disorder)
        row$Level3_Sankey_data <- c(row$Level3_Sankey_data, previous_exc_diag, currently_earliest_exc_disorder_numeric)
        row$Level3_Sankey_source <- c(row$Level3_Sankey_source, previous_exc_diag)
        row$Level3_Sankey_target <- c(row$Level3_Sankey_target, currently_earliest_exc_disorder_numeric)
        row$Level3_Sankey_value <- c(row$Level3_Sankey_value, 1)
        previous_exc_diag <- currently_earliest_exc_disorder_numeric
      }
    }
    temp_exc_diag <- temp_exc_diag[keep_pos]
    temp_exc_diag_date <- temp_exc_diag_date[keep_pos]
  }
  row$temp_exc_diag_date <- temp_exc_diag_date
  row$temp_exc_diag <- temp_exc_diag
  row
}

Build_sankey_data <- function(data, fn, iidcol, verbose = FALSE) {
  if (!"Level3_Sankey" %in% names(data)) data$Level3_Sankey <- replicate(nrow(data), list())
  if (!"Level3_Sankey_data" %in% names(data)) data$Level3_Sankey_data <- replicate(nrow(data), list())
  if (!"Level3_Sankey_source" %in% names(data)) data$Level3_Sankey_source <- replicate(nrow(data), list())
  if (!"Level3_Sankey_target" %in% names(data)) data$Level3_Sankey_target <- replicate(nrow(data), list())
  if (!"Level3_Sankey_value" %in% names(data)) data$Level3_Sankey_value <- replicate(nrow(data), list())
  data$Level3_Sankey[which(data$diagnosis == "Case")] <- lapply(data$Level3_Sankey[which(data$diagnosis == "Case")], function(x) c(x, "MDD"))
  data$temp_exc_diag_date <- data$date_Level2_modifier
  data$temp_exc_diag <- data$diagnoses_Level2_modifier
  # apply processors while any temp_exc_diag non-empty
  iter <- 0
  while (any(sapply(data$temp_exc_diag, function(x) length(x) > 0))) {
    data <- as.data.frame(t(apply(data, 1, function(r) {
      row <- as.list(r)
      row <- Sankey_build_processor(row)
      unlist(row)
    })), stringsAsFactors = FALSE)
    iter <- iter + 1
    if (iter > 10) break
  }
  # finalize and write sankey counts
  counts <- list()
  for (i in seq_len(nrow(data))) {
    if (data$diagnosis[i] == "Case") {
      srcs <- data$Level3_Sankey_source[[i]]
      tgs  <- data$Level3_Sankey_target[[i]]
      for (k in seq_along(srcs)) {
        key <- paste0(srcs[[k]], "->", tgs[[k]])
        counts[[key]] <- counts[[key]] %||% 0
        counts[[key]] <- counts[[key]] + 1
      }
    }
  }
  if (length(counts) > 0) {
    res_df <- data.frame(
      Source = vapply(names(counts), function(k) strsplit(k, "->")[[1]][1], character(1)),
      Target = vapply(names(counts), function(k) strsplit(k, "->")[[1]][2], character(1)),
      Value  = unname(unlist(counts)),
      stringsAsFactors = FALSE
    )
    sankey_fn <- paste0(tools::file_path_sans_ext(basename(fn)), ".sankey.tsv")
    tryCatch({
      write.table(res_df, file = sankey_fn, sep = "\t", row.names = FALSE, quote = FALSE)
    }, error = function(e) logger_info("[Build_sankey_data] Couldn't write sankey file:", e$message))
  }
  data$temp_exc_diag_date <- NULL
  data$temp_exc_diag <- NULL
  data
}

