# BuildEntryExitDate / load_config / load_stam_file / process_lpr_data / finalize_lpr_data / merge_secondary_diagnoses
# -----------------------------------------------------------------------------

BuildEntryExitDate <- function(df1, df3, iidcol, input_date_in_name, input_date_out_name, verbose = FALSE) {
  tmp <- df1[, c(iidcol, input_date_in_name, input_date_out_name), drop = FALSE]
  if (!input_date_in_name %in% names(tmp) && "date_in" %in% names(tmp)) input_date_in_name <- "date_in"
  if (!input_date_out_name %in% names(tmp) && "date_out" %in% names(tmp)) input_date_out_name <- "date_out"
  in_dates <- tmp %>% group_by_at(iidcol) %>% summarize(EntryDate = min(.data[[input_date_in_name]], na.rm = TRUE))
  if (input_date_out_name != input_date_in_name) out_dates <- tmp %>% group_by_at(iidcol) %>% summarize(ExitDate = max(.data[[input_date_out_name]], na.rm = TRUE)) else out_dates <- tmp %>% group_by_at(iidcol) %>% summarize(ExitDate = max(.data[[input_date_in_name]], na.rm = TRUE))
  entry_exit <- merge(as.data.frame(in_dates), as.data.frame(out_dates), by = iidcol)
  df3_new <- merge(df3, entry_exit, by = iidcol, all.x = TRUE)
  df3_new
}

load_config <- function(filename = "get_pheno.ini") {
  # look in script dir first
  script_dir <- dirname(normalizePath(sys.frame(1)$ofile, mustWork = FALSE))
  config_path <- file.path(script_dir, filename)
  if (!file.exists(config_path)) return(NULL)
  tryCatch({
    config <- config::get(file = config_path)
    config
  }, error = function(e) {
    NULL
  })
}

merge_secondary_diagnoses <- function(df1, df, diagnostic_col, lpr_recnummer, lpr2nd_recnummer, diagnostic2nd_col) {
  names(df)[names(df) == lpr2nd_recnummer] <- lpr_recnummer
  names(df)[names(df) == diagnostic2nd_col] <- diagnostic_col
  df1_temp <- merge(df[, c(diagnostic_col, lpr_recnummer), drop = FALSE], df1[ , setdiff(names(df1), diagnostic_col), drop = FALSE], by = lpr_recnummer, all = FALSE)
  df1_temp <- unique(df1_temp)
  if ("c_tildiag" %in% names(df1_temp) && "c_diagtype" %in% names(df1_temp)) {
    mask <- grepl("\\+", df1_temp$c_diagtype, fixed = TRUE)
    df1_temp[mask, diagnostic_col] <- df1_temp$c_tildiag[mask]
  }
  rbind(df1, df1_temp)
}

load_stam_file <- function(stam_file, isep = ",", birthdatecol = "birthdate", diagnostic_col = "diagnosis", sexcol = "sex", stam_cols_to_read_as_date = character()) {
  paths <- strsplit(stam_file, ",")[[1]] |> trimws()
  frames <- list()
  for (path in paths) {
    if (grepl("\\.dta$", path, ignore.case = TRUE)) {
      df <- haven::read_dta(path)
    } else {
      hdr <- tryCatch(read.csv(path, sep = isep, nrows = 1, stringsAsFactors = FALSE), error = function(e) data.frame())
      # read full
      df <- tryCatch(read.csv(path, sep = isep, stringsAsFactors = FALSE), error = function(e) read.csv(path, sep = isep, stringsAsFactors = FALSE))
      # parse dates
      date_cols <- intersect(stam_cols_to_read_as_date, names(df))
      for (col in date_cols) df[[col]] <- to_datetime_series(as.character(df[[col]]), fmt = DateFormat, dayfirst = DayFirst)
    }
    frames[[length(frames) + 1]] <- df
  }
  if (length(frames) == 0) return(data.frame())
  df3 <- bind_rows(frames)
  if (birthdatecol %in% names(df3) && birthdatecol != "birthdate") names(df3)[names(df3) == birthdatecol] <- "birthdate"
  if (diagnostic_col %in% names(df3) && diagnostic_col != "diagnosis") names(df3)[names(df3) == diagnostic_col] <- "diagnosis"
  if (sexcol %in% names(df3) && sexcol != "sex") names(df3)[names(df3) == sexcol] <- "sex"
  if ("birthdate" %in% names(df3) && !inherits(df3$birthdate, "POSIXct")) df3$birthdate <- to_datetime_series(as.character(df3$birthdate), fmt = DateFormat, dayfirst = DayFirst)
  # convert non-numeric object columns to character and then to string where mostly non-numeric
  for (c in names(df3)) {
    if (!inherits(df3[[c]], "POSIXct") && is.character(df3[[c]])) {
      num <- suppressWarnings(as.numeric(df3[[c]]))
      if (mean(!is.na(num)) < 0.5) df3[[c]] <- as.character(df3[[c]])
    }
  }
  df3
}

process_lpr_data <- function(lpr_file, lpr2nd_file = "", dta_input = FALSE, fsep = ",", lpr_cols_to_read_as_date = character(), DateFormat = "%Y-%m-%d", potential_lpr_cols_to_read_as_date = character(), diagnostic_col = "diagnosis", diagnostic2nd_col = "", lpr_recnummer = "", lpr2nd_recnummer = "") {
  file_paths <- strsplit(lpr_file, ",")[[1]] |> trimws()
  secondary_paths <- if (nzchar(lpr2nd_file)) strsplit(lpr2nd_file, ",")[[1]] |> trimws() else character(0)
  if (length(secondary_paths) > 0 && length(file_paths) != length(secondary_paths)) stop("Mismatch LPR and LPR2nd files")
  df1 <- NULL
  if (length(secondary_paths) > 0) {
    for (i in seq_along(file_paths)) {
      lprfile <- file_paths[i]; lpr2ndfile <- secondary_paths[i]
      df_lpr <- load_stam_file(lprfile, isep = fsep, birthdatecol = "", diagnostic_col = "", sexcol = "", stam_cols_to_read_as_date = unique(c(lpr_cols_to_read_as_date, potential_lpr_cols_to_read_as_date)))
      df_lpr2nd <- load_stam_file(lpr2ndfile, isep = fsep, birthdatecol = "", diagnostic_col = "", sexcol = "", stam_cols_to_read_as_date = unique(c(lpr_cols_to_read_as_date, potential_lpr_cols_to_read_as_date)))
      df_merged <- merge_secondary_diagnoses(df_lpr, df_lpr2nd, diagnostic_col, lpr_recnummer, lpr2nd_recnummer, diagnostic2nd_col)
      if (is.null(df1)) df1 <- df_merged else df1 <- bind_rows(df1, df_merged)
    }
  } else {
    for (lprfile in file_paths) {
      df_lpr <- load_stam_file(lprfile, isep = fsep, birthdatecol = "", diagnostic_col = "", sexcol = "", stam_cols_to_read_as_date = unique(c(lpr_cols_to_read_as_date, potential_lpr_cols_to_read_as_date)))
      if (is.null(df1)) df1 <- df_lpr else df1 <- bind_rows(df1, df_lpr)
    }
  }
  df1
}

finalize_lpr_data <- function(df1, diagnostic_col = "diagnosis", birthdatecol = "birthdate", ctype_col = "", verbose = FALSE) {
  if (diagnostic_col %in% names(df1) && diagnostic_col != "diagnosis") names(df1)[names(df1) == diagnostic_col] <- "diagnosis"
  if (birthdatecol %in% names(df1) && birthdatecol != "birthdate") names(df1)[names(df1) == birthdatecol] <- "birthdate"
  if ("c_pattype" %in% names(df1)) names(df1)[names(df1) == "c_pattype"] <- "pattype"
  if ("c_indm" %in% names(df1)) names(df1)[names(df1) == "c_indm"] <- "admissiontype"
  if (nzchar(ctype_col) && ctype_col %in% names(df1)) names(df1)[names(df1) == ctype_col] <- "diagtype"
  if ("source" %in% names(df1)) names(df1)[names(df1) == "source"] <- "register"
  if ("diag_source" %in% names(df1)) names(df1)[names(df1) == "diag_source"] <- "source"
  df1
}

# -----------------------------------------------------------------------------
# process_pheno_and_exclusions: main pipeline (translated)
# -----------------------------------------------------------------------------

process_pheno_and_exclusions <- function(MatchFI, df1, df3, df4 = data.frame(), iidcol, verbose = FALSE, ctype_excl = "", ctype_incl = "", ctype_col = "", Filter_YoB = "", Filter_Gender = "", use_predefined_exdep_exclusions = FALSE, cluster_run = "Default", exact_match = FALSE, skip_icd_update = FALSE, remove_point_in_diag_request = FALSE, ICDCM = FALSE, qced_iids = "", general_exclusions = "", multi_inclusions = FALSE, in_pheno_codes = data.frame(), pheno_requestcol = "", diagnostic_col = "diagnosis", atc_diag_col = "", birthdatecol = "birthdate", atc_date_col = "", atc_cols_to_read_as_date = character(), atc_file = "", fsep = ",", BuildEntryExitDates = FALSE, lifetime_exclusions_file = "", post_exclusions_file = "", oneYearPrior_exclusions_file = "", outfile = "out.tsv", write_Plink2_format = FALSE, write_fastGWA_format = FALSE, write_pickle = FALSE, n_stam_iids = 0, exclCHBcontrols = FALSE, iidstatus_col = "", iidstatusdate = "", addition_information_file = "", sexcol = "sex", input_date_in_name = "date_in", input_date_out_name = "date_out", append = FALSE, icdprefix = "", noLeadingICD = FALSE, lifetime_exclusions = data.frame(), oneYearPrior_exclusions = data.frame(), post_exclusions = data.frame(), covariates = data.frame()) {
  logger_info("[process_pheno_and_exclusions] Starting")
  # Restrict df1 by df3
  if (MatchFI) {
    logger_info("[process_pheno_and_exclusions] Restraining df1 and df3 to overlapping IIDs")
    common <- intersect(df1[[iidcol]], df3[[iidcol]])
    df1 <- df1[df1[[iidcol]] %in% common, , drop = FALSE]
    df3 <- df3[df3[[iidcol]] %in% common, , drop = FALSE]
  } else {
    if (nrow(df3) > 0) df1 <- df1[df1[[iidcol]] %in% df3[[iidcol]], , drop = FALSE]
  }
  if (nrow(df1) == 0) stop("[process_pheno_and_exclusions] No IIDs left after filtering")
  # Prepare phenotype codes
  tmp_cases_df <- data.frame()
  extra_cols_to_keep <- if (cluster_run %in% DK_clusters) c("admissiontype", "pattype", "diagtype", "source", "register") else character(0)
  if (ATC_Requested %in% c("All", "Some") && nzchar(atc_file)) {
    atc_df1 <- load_stam_file(atc_file, isep = fsep, birthdatecol = "", diagnostic_col = atc_diag_col, sexcol = "", stam_cols_to_read_as_date = atc_cols_to_read_as_date)
    atc_df1 <- finalize_lpr_data(atc_df1, diagnostic_col = atc_diag_col, birthdatecol = atc_date_col, ctype_col = ctype_col, verbose = verbose)
  } else atc_df1 <- data.frame()
  # iterate phenotypes in in_pheno_codes (data.frame with Disorder / Disorder Codes)
  for (InclusionReason in in_pheno_codes$Disorder) {
    logger_info("[process_pheno_and_exclusions] Building CaseControl for", InclusionReason)
    values_to_match <- unlist(in_pheno_codes$`Disorder Codes`[in_pheno_codes$Disorder == InclusionReason][[1]])
    # handle ATC partitions
    if (InclusionReason == "ATC" && nzchar(atc_file)) {
      filtered_df <- build_phenotype_cases(df1 = atc_df1, exact_match = exact_match, values_to_match = values_to_match, diagnostic_col = atc_diag_col, birthdatecol = birthdatecol, iidcol = iidcol, input_date_in_name = atc_date_col, input_date_out_name = atc_date_col, verbose = verbose, Covariates = TRUE, Covar_Name = InclusionReason, skip_icd_update = skip_icd_update, remove_point_in_diag_request = remove_point_in_diag_request, ICDCM = ICDCM, noLeadingICD = noLeadingICD, icdprefix = icdprefix)
    } else {
      filtered_df <- build_phenotype_cases(df1 = df1, exact_match = exact_match, values_to_match = values_to_match, diagnostic_col = diagnostic_col, birthdatecol = birthdatecol, iidcol = iidcol, input_date_in_name = input_date_in_name, input_date_out_name = input_date_out_name, verbose = verbose, Covariates = TRUE, Covar_Name = InclusionReason, skip_icd_update = skip_icd_update, remove_point_in_diag_request = remove_point_in_diag_request, ICDCM = ICDCM, noLeadingICD = noLeadingICD, icdprefix = icdprefix)
    }
    available_cols <- intersect(c(iidcol, "diagnosis", "diagnoses", "in_dates", "out_dates", "first_dx", "last_dx", "n_diags", "n_unique_in_days", extra_cols_to_keep), names(filtered_df))
    filtered_df <- filtered_df[, available_cols, drop = FALSE]
    if (nrow(filtered_df) > 0) {
      # rename mapped columns with prefix
      base_map <- list("diagnosis" = InclusionReason, "diagnoses" = paste0(InclusionReason, "_Codes"), "in_dates" = paste0(InclusionReason, "_In_Dates"), "out_dates" = paste0(InclusionReason, "_Out_Dates"), "first_dx" = paste0(InclusionReason, "_earliest_date"), "last_dx" = paste0(InclusionReason, "_latest_date"), "n_diags" = paste0(InclusionReason, "_n_diags"), "n_unique_in_days" = paste0(InclusionReason, "_n_unique_in_days"))
      for (k in names(base_map)) if (k %in% names(filtered_df)) names(filtered_df)[names(filtered_df) == k] <- base_map[[k]]
      for (col in extra_cols_to_keep) if (col %in% names(filtered_df)) names(filtered_df)[names(filtered_df) == col] <- paste0(InclusionReason, "_", col)
      if (nrow(tmp_cases_df) == 0) tmp_cases_df <- filtered_df else tmp_cases_df <- merge(tmp_cases_df, filtered_df, by = iidcol, all = TRUE)
    } else {
      # ensure columns exist in tmp_cases_df even if empty
      fixed_suffixes <- c("", "_Codes", "_In_Dates", "_Out_Dates", "_earliest_date", "_latest_date", "_n_diags", "_n_unique_in_days")
      for (suf in fixed_suffixes) {
        col <- paste0(InclusionReason, suf)
        if (!col %in% names(tmp_cases_df)) tmp_cases_df[[col]] <- ""
      }
      for (col in extra_cols_to_keep) {
        newcol <- paste0(InclusionReason, "_", col)
        if (!newcol %in% names(tmp_cases_df)) tmp_cases_df[[newcol]] <- ""
      }
    }
  }
  if (nrow(tmp_cases_df) == 0) stop("[process_pheno_and_exclusions] Error: No Cases found")
  casecontrol_df <- tmp_cases_df
  # merge with df3 (stam)
  result_df <- merge(casecontrol_df, df3, by = iidcol, all.y = TRUE)
  result_df$diagnosis[!(result_df$diagnosis %in% c("Case", "Control", "Case_Excluded"))] <- "Control"
  # compute Age_FirstDx for Cases
  case_mask <- result_df$diagnosis == "Case"
  if (any(case_mask, na.rm = TRUE)) {
    first_dx <- result_df$first_dx
    birth <- if ("birthdate" %in% names(result_df)) result_df$birthdate else rep(NA, nrow(result_df))
    first_dx_parsed <- sapply(first_dx, convert_if_not_datetime)
    birth_parsed <- sapply(birth, convert_if_not_datetime)
    age_first_dx <- floor(as.numeric(difftime(first_dx_parsed, birth_parsed, units = "days")) / 365)
    age_first_dx[is.na(age_first_dx)] <- 0
    result_df$Age_FirstDx <- age_first_dx
  } else {
    result_df$Age_FirstDx <- 0
  }
  final_df <- result_df
  # apply exclusion interpreter if exclusions present
  if ((nrow(oneYearPrior_exclusions) > 0) || (nrow(post_exclusions) > 0) || (nrow(lifetime_exclusions) > 0)) {
    cols_to_use <- c(iidcol, 'diagnosis', 'diagnoses', 'first_dx', 'in_dates', 'birthdate', 'Age_FirstDx')
    tmp_final_df <- final_df[final_df$diagnosis == "Case", cols_to_use]
    excl_interpreted <- Exclusion_interpreter(tmp_final_df, min_Age = min_Age, max_Age = max_Age, lifetime_exclusions = lifetime_exclusions, oneYearPrior_exclusions = oneYearPrior_exclusions, post_exclusions = post_exclusions, verbose = verbose)
    final_df <- merge(final_df, excl_interpreted, by = iidcol, all.x = TRUE)
  }
  # finalize, write output
  write_header <- !append
  write.table(final_df, file = outfile, sep = "\t", row.names = FALSE, col.names = write_header, append = append, quote = FALSE)
  # reformat naive replacements to remove list-markers
  # TODO: convert list-columns to comma-strings consistently
  if (write_pickle) saveRDS(final_df, paste0(outfile, ".rds"))
  if (!"IID" %in% names(final_df)) final_df$IID <- final_df[[iidcol]]
  if (write_fastGWA_format) {
    final_df$FID <- final_df$IID
    final_df$CaseControl <- ifelse(final_df$diagnosis == "Case", "1", "0")
    write.table(final_df[, c("FID", "IID", "CaseControl")], paste0(outfile, ".fgwa.pheno"), sep = "\t", row.names = FALSE, quote = FALSE)
  }
  if (write_Plink2_format) {
    final_df$`#FID` <- final_df$IID
    final_df$CaseControl <- ifelse(final_df$diagnosis == "Case", "2", "1")
    write.table(final_df[, c("#FID", "IID", "CaseControl")], paste0(outfile, ".plink2.pheno"), sep = "\t", row.names = FALSE, quote = FALSE)
  }
  logger_info("[process_pheno_and_exclusions] Finished. Output:", outfile)
  invisible(final_df)
}


# ---- CLI entrypoint for Rscript (full parity with Python argparse flags) ----
if (!interactive()) {
  parse_bool <- function(x) {
    if (is.null(x) || x == "") return(FALSE)
    tolower(as.character(x)) %in% c("true", "1", "t", "y", "yes")
  }

  parse_args <- function(argv) {
    res <- list()
    for (a in argv) {
      # Accept forms: --long=val  --flag  -s=val  -s
      if (!grepl("^-", a)) next
      kv <- sub("^--?", "", a)
      if (grepl("=", kv)) {
        parts <- strsplit(kv, "=", fixed = TRUE)[[1]]
        key <- parts[1]; val <- paste(parts[-1], collapse = "=")
        res[[key]] <- val
      } else {
        # flag without value => TRUE
        res[[kv]] <- "TRUE"
      }
    }
    res
  }

  # Known flags and Python defaults (kept for parity)
  known_defaults <- list(
    ini = "",
    g = "",
    o = "",
    f = "",
    f2 = "",
    atc = "",
    i = "",
    j = "",
    ge = "",
    qced = "",
    name = "MainPheno",
    fcol = "c_adiag",
    gcol = "c_adiag",
    iidcol = "pnr",
