    BuildOphold = "FALSE",
    RegisterRun = "FALSE",
    lpp = "FALSE",
    write_pickle = "FALSE",
    write_fastGWA_format = "FALSE",
    write_Plink2_format = "FALSE",
    BuildTestSet = "FALSE",
    testRun = "FALSE",
    nthreads = "8",
    lowmem = "FALSE",
    batchsize = "100000",
    PSYK = "FALSE",
    LPR = "FALSE",
    BuildIndex = "FALSE",
    IndexDtypes = '{"iidcol":"int","c_pattype":"float","c_adiag":"string","c_diagtype": "string","register":"string","source":"string","d_inddto":"datetime64[ns]","d_uddto":"datetime64[ns]"}',
    verbose = "FALSE",
    ophsep = ",",
    LPR = "FALSE",
    PSYK = "FALSE"
  )

  argv <- commandArgs(trailingOnly = TRUE)
  if (length(argv) > 0) {
    raw_args <- parse_args(argv)

    # produce final args by merging provided with defaults
    final_args <- known_defaults
    for (k in names(known_defaults)) {
      if (!is.null(raw_args[[k]])) final_args[[k]] <- raw_args[[k]]
      # also accept the single-letter short aliases used in Python (-g, -f, -i, -j, -o, -n threads etc.)
      short_aliases <- list(f = "f", g = "g", i = "i", j = "j", o = "o", nthreads = "nthreads")
      if (k %in% names(short_aliases) && !is.null(raw_args[[short_aliases[[k]]]])) final_args[[k]] <- raw_args[[short_aliases[[k]]]]
    }

    # Build argstring and default lists similar to Python script
    arg_lines <- character(0)
    default_args <- character(0)
    default_argstring_lines <- character(0)
    for (k in names(known_defaults)) {
      provided_val <- final_args[[k]]
      default_val  <- known_defaults[[k]]
      if (!identical(as.character(provided_val), as.character(default_val))) {
        arg_lines <- c(arg_lines, paste0("--", k, ": ", provided_val, " (default: ", default_val, ")"))
      } else {
        default_args <- c(default_args, paste0("--", k))
        default_argstring_lines <- c(default_argstring_lines, paste0("--", k, ": ", provided_val, " (default: ", default_val, ")"))
      }
    }
    argstring <- paste(arg_lines, collapse = "\n")
    default_argstring <- paste(default_argstring_lines, collapse = "\n")

    # convert booleans/typed values
    bool <- function(x) parse_bool(as.character(x))
    # Map frequently-used flags to local variables for the pipeline
    lpr_file <- final_args[["f"]]
    lpr2_file <- final_args[["f2"]]
    atc_file <- final_args[["atc"]]
    stam_file <- final_args[["i"]]
    addition_file <- final_args[["j"]]
    in_pheno_path <- final_args[["g"]]
    outfile <- final_args[["o"]]
    iidcol <- final_args[["iidcol"]]
    diagnostic_col <- final_args[["fcol"]]
    birthdatecol <- final_args[["bdcol"]]
    sexcol <- final_args[["sexcol"]]
    atc_diag_col <- final_args[["atccol"]]
    atc_date_col <- final_args[["atcdatecol"]]
    fsep <- final_args[["fsep"]]
    isep <- final_args[["isep"]]
    jsep <- final_args[["jsep"]]
    gsep <- final_args[["gsep"]]
    MatchFI <- bool(final_args[["MatchFI"]])
    exact_match <- bool(final_args[["eM"]])
    skip_icd_update <- bool(final_args[["skipICDUpdate"]])
    remove_point_in_diag_request <- bool(final_args[["removePointInDiagCode"]])
    ICDCM <- bool(final_args[["ICDCM"]])
    noLeadingICD <- bool(final_args[["noLeadingICD"]])
    verbose <- bool(final_args[["verbose"]])
    BuildEntryExitDates <- bool(final_args[["BuildEntryExitDates"]])
    write_pickle <- bool(final_args[["write_pickle"]])
    write_fastGWA_format <- bool(final_args[["write_fastGWA_format"]])
    write_Plink2_format <- bool(final_args[["write_Plink2_format"]])
    BuildTestSet <- bool(final_args[["BuildTestSet"]])
    testRun <- bool(final_args[["testRun"]])
    lowmem <- bool(final_args[["lowmem"]])
    batchsize <- as.integer(final_args[["batchsize"]])
    ExDepExc <- bool(final_args[["ExDepExc"]])
    eCc <- bool(final_args[["eCc"]])
    nthreads <- as.integer(final_args[["nthreads"]])
    icdprefix <- final_args[["icdprefix"]]
    DateFormat <- final_args[["DateFormat"]]
    MinMaxAge <- final_args[["MinMaxAge"]]
    mm <- strsplit(as.character(MinMaxAge), ",", fixed = TRUE)[[1]]
    min_Age <- as.numeric(mm[1]); max_Age <- if (length(mm) >= 2) as.numeric(mm[2]) else 0
    if (is.na(min_Age)) min_Age <- 0
    if (is.na(max_Age)) max_Age <- 0

    # Load data files (best-effort: accept comma-separated paths as in Python)
    if (nzchar(as.character(lpr_file))) {
      # allow several comma-separated lpr parts
      df1 <- process_lpr_data(lpr_file = as.character(lpr_file), lpr2nd_file = as.character(lpr2_file), dta_input = FALSE, fsep = as.character(fsep), lpr_cols_to_read_as_date = character(), DateFormat = DateFormat)
    } else stop("LPR file required via -f/--f")

    if (nzchar(as.character(stam_file))) {
      df3 <- load_stam_file(as.character(stam_file), isep = as.character(isep), birthdatecol = birthdatecol, diagnostic_col = diagnostic_col, sexcol = sexcol)
    } else stop("stam file required via -i/--i")

    if (nzchar(as.character(addition_file))) {
      df4 <- load_stam_file(as.character(addition_file), isep = as.character(jsep), birthdatecol = "", diagnostic_col = "", sexcol = "")
    } else df4 <- data.frame()

    # load phenotype definitions expected in -g (CSV or JSON)
    if (!nzchar(as.character(in_pheno_path))) stop("Phenotype definitions required via -g")
    if (grepl("\\.json$", in_pheno_path, ignore.case = TRUE)) {
      ph <- jsonlite::fromJSON(in_pheno_path)
      in_pheno_codes_df <- if (is.data.frame(ph)) ph else as.data.frame(ph)
    } else {
      ph <- read.csv(in_pheno_path, sep = gsep, stringsAsFactors = FALSE)
      if ("Disorder Codes" %in% names(ph)) {
        ph$`Disorder Codes` <- lapply(ph$`Disorder Codes`, function(x) {
          if (is.na(x) || x == "") return(character(0))
          toks <- unlist(strsplit(as.character(x), "[,;|]", perl = TRUE))
          trimws(toks)
        })
      } else if ("Codes" %in% names(ph)) {
        ph$`Disorder Codes` <- lapply(ph$Codes, function(x) trimws(unlist(strsplit(as.character(x), "[,;|]"))))
      }
      in_pheno_codes_df <- ph
    }

    # export globals
    cluster_run <<- cluster_run
    verbose <<- verbose
    ATC_Requested <<- if (nzchar(as.character(atc_file))) "Some" else "NotSet"
    min_Age <<- min_Age
    max_Age <<- max_Age

    # call main pipeline (we forward many common args; parser keeps parity of flags)
    res <- process_pheno_and_exclusions(
      MatchFI = MatchFI,
      df1 = df1,
      df3 = invisible(df3),
      df4 = df4,
      iidcol = iidcol,
      verbose = verbose,
      cluster_run = cluster_run,
      exact_match = exact_match,
      skip_icd_update = skip_icd_update,
      remove_point_in_diag_request = remove_point_in_diag_request,
      ICDCM = ICDCM,
      noLeadingICD = noLeadingICD,
      icdprefix = icdprefix,
      in_pheno_codes = in_pheno_codes_df,
      outfile = outfile,
      atc_file = as.character(atc_file),
      atc_diag_col = atc_diag_col,
      atc_date_col = atc_date_col,
      fsep = fsep,
      BuildEntryExitDates = BuildEntryExitDates,
      write_pickle = write_pickle,
      write_fastGWA_format = write_fastGWA_format,
      write_Plink2_format = write_Plink2_format
    )

    # Print arg summaries (like your Python script)
    message("Provided args (non-default):\n", argstring)
    message("Provided args kept at default (--listed):\n", paste(default_args, collapse = ", "))
    message("Default args detail:\n", default_argstring)
    message("Wrote output to: ", outfile)
  } else {
    # no args — do nothing (script likely being sourced)
  }
}

