### --- Python parity compatibility layer ---


parse_cli_args <- function() {
  args <- commandArgs(trailingOnly = TRUE)
  out <- list()
  i <- 1
  while (i <= length(args)) {
    a <- args[[i]]
    if (grepl("^--", a)) {
      if (grepl("=", a)) {
        kv <- strsplit(sub("^--", "", a), "=", fixed = TRUE)[[1]]
        key <- kv[[0+1]]; val <- paste(kv[-1], collapse="=")
        # Cast booleans and numbers when possible
        if (tolower(val) %in% c("true","false")) {
          out[[key]] <- tolower(val) == "true"
        } else if (grepl("^[+-]?[0-9]+$", val)) {
          out[[key]] <- as.integer(val)
        } else if (grepl("^[+-]?[0-9]*\\.?[0-9]+$", val)) {
          out[[key]] <- as.numeric(val)
        } else {
          out[[key]] <- val
        }
      } else {
        key <- sub("^--", "", a)
        # standalone flags act as TRUE
        out[[key]] <- TRUE
      }
    } else {
      # positional arguments are collected
      idx <- length(out[["__positional__"]]) + 1
      if (is.null(out[["__positional__"]])) idx <- 1
      if (is.null(out[["__positional__"]])) out[["__positional__"]] <- character()
      out[["__positional__"]][idx] <- a
    }
    i <- i + 1
  }
  class(out) <- c("pheno_args", class(out))
  return(out)
}

get_arg <- function(args, key, default = NULL) {
  if (!is.list(args)) return(default)
  if (!is.null(args[[key]])) return(args[[key]])
  return(default)
}

setup_logger <- function(verbose=TRUE) {
  assign(".PHENO_VERBOSE", isTRUE(verbose), envir = .GlobalEnv)
}

.log <- function(..., level="INFO") {
  verbose <- get(".PHENO_VERBOSE", envir=.GlobalEnv, inherits=FALSE)
  if (isTRUE(verbose) || level %in% c("ERROR","WARN")) {
    t <- format(Sys.time(), "%Y-%m-%d %H:%M:%S")
    msg <- paste0("[", t, "] [", level, "] ", paste(..., collapse=" "))
    writeLines(msg)
  }
}

# Utility conversions
_as_list <- function(x) {
  if (is.null(x)) return(list())
  if (is.list(x)) return(x)
  if (is.vector(x)) return(as.list(x))
  list(x)
}

_to_datetime_series <- function(x, date_format=NULL) {
  if (is.null(x)) return(x)
  if (!is.character(x)) x <- as.character(x)
  if (!is.null(date_format)) {
    suppressWarnings(as.POSIXct(x, format=date_format, tz="UTC"))
  } else {
    suppressWarnings(as.POSIXct(x, tz="UTC"))
  }
}

_normalize_dates <- function(df, cols, date_format=NULL) {
  for (c in cols) {
    if (c %in% names(df)) {
      df[[c]] <- _to_datetime_series(df[[c]], date_format=date_format)
    }
  }
  df
}

# String helpers
_norm_list <- function(x, sep=",") {
  if (is.null(x)) return(character())
  if (is.logical(x) && length(x)==1 && isTRUE(x)) return(character())
  if (is.list(x)) x <- unlist(x, use.names=FALSE)
  if (length(x)==1 && is.character(x) && grepl(sep, x, fixed=TRUE)) {
    x <- strsplit(x, sep, fixed=TRUE)[[1]]
  }
  trimws(as.character(x))
}

# ICD/ATC helpers
is_advanced <- function(val) {
  is.character(val) && any(grepl("(main=|sub=|rule_out=|\\-)", val))
}

expand_ranges <- function(x) {
  # Basic range expander supporting "A1-A3", "36-38", "ICD10:T36-ICD10:T38"
  x <- _norm_list(x, sep=",")
  out <- character()
  for (tok in x) {
    tok <- trimws(tok)
    m <- regexec("^([A-Za-z0-9:]+)\\-([A-Za-z0-9:]+)$", tok)
    mm <- regmatches(tok, m)[[1]]
    if (length(mm) == 3) {
      a <- mm[2]; b <- mm[3]
      # if prefixed forms like "ICD10:T36-ICD10:T38"
      pref_a <- sub("^([^:]+:).*", "\\1", a)
      pref_b <- sub("^([^:]+:).*", "\\1", b)
      if (grepl(":", a) && grepl(":", b) && pref_a == pref_b) {
        a2 <- sub("^[^:]+:", "", a)
        b2 <- sub("^[^:]+:", "", b)
        if (grepl("^[A-Za-z]?[0-9]+$", a2) && grepl("^[A-Za-z]?[0-9]+$", b2)) {
          # strip optional letter and expand numerically
          la <- sub("([A-Za-z]?)[0-9]+$", "\\1", a2)
          lb <- sub("([A-Za-z]?)[0-9]+$", "\\1", b2)
          na <- as.integer(gsub("^[A-Za-z]", "", a2))
          nb <- as.integer(gsub("^[A-Za-z]", "", b2))
          if (identical(la, lb) && !is.na(na) && !is.na(nb)) {
            for (i in seq(na, nb)) out <- c(out, paste0(pref_a, la, i))
            next
          }
        }
      }
      # plain numeric ranges
      if (grepl("^[0-9]+$", a) && grepl("^[0-9]+$", b)) {
        for (i in seq(as.integer(a), as.integer(b))) out <- c(out, as.character(i))
        next
      }
      # alpha+numeric like T36-T38
      if (grepl("^[A-Za-z][0-9]+$", a) && grepl("^[A-Za-z][0-9]+$", b) &&
          substr(a,1,1)==substr(b,1,1)) {
        la <- substr(a,1,1); na <- as.integer(sub("^[A-Za-z]", "", a))
        lb <- substr(b,1,1); nb <- as.integer(sub("^[A-Za-z]", "", b))
        if (!is.na(na) && !is.na(nb) && la==lb) {
          for (i in seq(na, nb)) out <- c(out, paste0(la, i))
          next
        }
      }
      # fallback: keep token as is
      out <- c(out, tok)
    } else {
      out <- c(out, tok)
    }
  }
  unique(out)
}

detect_ATC_status <- function(vec) {
  vals <- _norm_list(vec)
  if (length(vals)==0) return("None")
  if (all(startsWith(vals, "ATC"))) return("All")
  if (any(startsWith(vals, "ATC"))) return("Some")
  "None"
}

normalize_iid_series <- function(x, target="str") {
  x <- as.character(x)
  x <- gsub("\\\\.0$", "", trimws(x))
  if (identical(target, "str")) return(x)
  if (any(!grepl("^\\d+$", x))) {
    .log("Non-numeric IIDs detected; returning strings", level="WARN")
    return(x)
  }
  suppressWarnings(as.integer(x))
}

# Matching codes (simple contains/prefix matching with optional dot removal)
match_codes <- function(codes, patterns, remove_point=FALSE, icd_prefix=NULL) {
  if (is.null(codes) || is.null(patterns)) return(rep(FALSE, length(codes)))
  codes2 <- as.character(codes)
  if (isTRUE(remove_point)) codes2 <- gsub("\\\\.", "", codes2)
  pats <- expand_ranges(patterns)
  pats <- gsub("^ICD10:", "", pats) # normalize
  pats <- unique(pats)
  res <- rep(FALSE, length(codes2))
  for (p in pats) {
    if (nzchar(p)) {
      if (remove_point) p2 <- gsub("\\\\.", "", p) else p2 <- p
      res <- res | startsWith(codes2, p2)
    }
  }
  res
}

