usage <- function() {
  writeLines("Usage: Rscript get_pheno.R --BuildIndex --LPR path --ICD10 T36-T38 --out out.tsv [--verbose true] ...")
}

main <- function() {
  args <- parse_cli_args()
  setup_logger(verbose = isTRUE(get_arg(args, "verbose", TRUE)))
  # Route by build flags
  if (isTRUE(get_arg(args, "BuildIndex", FALSE))) {
    infile <- get_arg(args, "LPR", NULL)
    outidx <- get_arg(args, "indexOut", get_arg(args, "out_index", "lpr_index.rds"))
    if (is.null(infile)) stop("--LPR (input) not provided for --BuildIndex")
    .log("Building index for", infile)
    meta <- index_diag_file(infile, outidx)
    .log("Wrote index meta to", outidx)
    return(invisible(meta))
  }
  if (isTRUE(get_arg(args, "BuildOphold", FALSE))) {
    inoph <- get_arg(args, "Ophold", NULL)
    out <- get_arg(args, "out", "ophold.tsv")
    if (is.null(inoph)) stop("--Ophold not provided for --BuildOphold")
    .log("Loading Ophold from", inoph)
    df <- tryCatch(read.csv(inoph, sep="\t", header=TRUE, check.names=FALSE), error=function(e) NULL)
    if (is.null(df)) stop("Failed to read Ophold: ", inoph)
    df2 <- process_ophold(df)
    reformat_to_tsv(df2, out)
    .log("Wrote Ophold TSV to", out)
    return(invisible(out))
  }
  if (isTRUE(get_arg(args, "BuildEntryExitDates", FALSE))) {
    inlpr <- get_arg(args, "LPR", NULL)
    date_format <- get_arg(args, "DateFormat", NULL)
    out <- get_arg(args, "out", "entry_exit.tsv")
    if (is.null(inlpr)) stop("--LPR not provided for --BuildEntryExitDates")
    .log("Computing Entry/Exit dates from", inlpr)
    df <- tryCatch(read.csv(inlpr, sep="\t", header=TRUE, check.names=FALSE), error=function(e) NULL)
    if (is.null(df)) stop("Failed to read LPR file: ", inlpr)
    date_cols <- c("date","start_date","end_date")
    df <- _normalize_dates(df, intersect(names(df), date_cols), date_format)
    # Minimal demo: by IID, min(start) and max(end)
    idcol <- get_arg(args, "iidcol", get_arg(args, "IID", "IID"))
    if (!idcol %in% names(df)) {
      .log("IID column not found; using first column", level="WARN")
      idcol <- names(df)[1]
    }
    if (!"start_date" %in% names(df) && "date" %in% names(df)) df$start_date <- df$date
    if (!"end_date" %in% names(df) && "date" %in% names(df)) df$end_date <- df$date
    agg <- stats::aggregate(cbind(start_date, end_date) ~ df[[idcol]], data=df,
                            FUN=function(x) c(min=min(x, na.rm=TRUE), max=max(x, na.rm=TRUE)))
    # Tidy aggregate
    agg_out <- data.frame(
      IID = df[[idcol]][match(unique(df[[idcol]]), df[[idcol]])][seq_len(nrow(agg))],
      entry_date = as.POSIXct(agg$start_date[, "min"], origin="1970-01-01", tz="UTC"),
      exit_date  = as.POSIXct(agg$end_date[, "max"],   origin="1970-01-01", tz="UTC")
    )
    reformat_to_tsv(agg_out, out)
    .log("Wrote entry/exit TSV to", out)
    return(invisible(out))
  }
  if (isTRUE(get_arg(args, "BuildTestSet", FALSE))) {
    out <- get_arg(args, "out", "test_dataset.tsv")
    n <- get_arg(args, "n", 1000L)
    set.seed(1)
    df <- data.frame(IID=seq_len(n), Disorder=sample(c(0,1), n, replace=TRUE))
    reformat_to_tsv(df, out)
    .log("Wrote test dataset to", out)
    return(invisible(out))
  }
  usage()
  invisible(NULL)
}

if (identical(environment(), globalenv())) {
  # Only run main() when executed as a script
  tryCatch(main(), error=function(e) { 
    writeLines(paste("ERROR:", conditionMessage(e))); 
    quit(status=1) 
  })
}
